class BouquinRepository extends \Doctrine\ORM\EntityRepository
{
    /*
    
    $qb->select('distri')
                    ->from($this->_entityName, 'distri')
                    ->addSelect('distri')
                    ->where($qb->expr()->notIn('distri.id', ':subQuery'))
                    ->orderBy('distri.nomDis')
                    ->setParameter('subQuery', $subQuery);
    */
    
    public function BouquinAll($directionid) {
        $qb = $this->createQueryBuilder('b');
        $qb->join('b.droit','d')
                ->addSelect('d')
                ->join('d.directions','dir')
                ->where($qb->expr()->In('distri.id', ':subQuery'))
                //->where("c.agent =:agent")
                ->andWhere("c.typeConges =:typeConges")
                ->andWhere("c.etat >=:etat")
                ->setParameter("agent", $agentid)
                ->setParameter("etat", $etat)
                ->setParameter("typeConges", $typeConges);
        return $qb->getQuery()->getOneOrNullResult();
    }
}
